    const focus = document.createElement('button'); focus.textContent = `# ${id}`;
    focus.title = cache.has(id) ? t("{0} · 点击单独查看", [sizeText(cache.get(id))]) : t('单独查看楼栋 ') + id;
    focus.onclick = () => selectIds([id]);
